          <h2 className="mt-1 text-xl font-semibold text-ink">{asset ? displayStatTicker(asset.ticker) : locale === "en" ? "No asset selected" : "Sin activo seleccionado"}</h2>
        </div>
        <button
          type="button"
          onClick={() => setOpen((value) => !value)}
